head.script:
scwin.onpageload = function () {
    scwin.generateRandomData();
};

// 100개 랜덤 데이터 생성
scwin.generateRandomData = function (append) {
    var data = [];
    var issueTpArr = ["사업자등록번호", "주민등록번호"];
    var donateTpArr = ["종교단체외(지정)", "특례(법정)", "고향사랑(재난지역)"];
    var gubunArr = ["현금"];
    var donorArr = ["단체테스트1", "단체테스트2", "일반과세사업자"];

    for (var i = 0; i < 100; i++) {
        var month = "07";
        var day = String(Math.floor(Math.random() * 28) + 1).padStart(2, "0");
        var amt = Math.floor(Math.random() * 100000) + 1;

        // 납세자번호: 사업자번호 형태 또는 주민번호 형태
        var taxId;
        var issueTp = issueTpArr[Math.floor(Math.random() * issueTpArr.length)];
        if (issueTp === "사업자등록번호") {
            taxId = "101-22-345**";
        } else {
            taxId = String(Math.floor(Math.random() * 90000) + 10000) + "********";
        }

        data.push({
            no: String(i + 1),
            donateDt: "2025." + month + "." + day + ".",
            applyDt: "2025." + month + "." + day + ".",
            procDt: "2025." + month + "." + day + ".",
            taxId: taxId,
            donor: donorArr[Math.floor(Math.random() * donorArr.length)],
            issueTp: issueTp,
            donateTp: donateTpArr[Math.floor(Math.random() * donateTpArr.length)],
            gubun: gubunArr[Math.floor(Math.random() * gubunArr.length)],
            refNo: String(Math.floor(Math.random() * 10) + 1),
            amt: String(amt),
        });
    }

    dataList1.setJSON(data, append === true);
    scwin.updateLoadMoreStatus();
    console.log(append === true ? "100개 랜덤 데이터 append 완료!" : "100개 랜덤 데이터 생성 완료!");
};

scwin.onpageunload = function () {

};

// ============================================================================
// Load More
// ============================================================================

scwin.btnLoadMore_onclick = function () {
    var result = listView1.loadMore();
    scwin.updateLoadMoreStatus(result);
    checkAll.setValue("");
};

scwin.btnLoadMore20_onclick = function () {
    var result = listView1.loadMore(20);
    scwin.updateLoadMoreStatus(result);
    checkAll.setValue("");
};

scwin.updateLoadMoreStatus = function(result) {
    var viewRowCount = listView1.getViewRowCount();
    var totalRowCount = dataList1.getRowCount();
    var hasMore = result ? result.hasMore : viewRowCount < totalRowCount;
    var statusLabel = "표시 " + viewRowCount + " / 전체 " + totalRowCount;

    if (result) {
        statusLabel += " (이전 " + result.oldRowCount + ", 현재 " + result.newRowCount + ")";
    }

    if (typeof tbxLoadMoreStatus !== "undefined" && tbxLoadMoreStatus && typeof tbxLoadMoreStatus.setLabel === "function") {
        tbxLoadMoreStatus.setLabel(statusLabel);
    }
    if (typeof btnLoadMore !== "undefined" && btnLoadMore && typeof btnLoadMore.setDisabled === "function") {
        btnLoadMore.setDisabled(!hasMore);
    }
    if (typeof btnLoadMore20 !== "undefined" && btnLoadMore20 && typeof btnLoadMore20.setDisabled === "function") {
        btnLoadMore20.setDisabled(!hasMore);
    }
    if (typeof btnLoadMore !== "undefined" && btnLoadMore && typeof btnLoadMore.setLabel === "function") {
        btnLoadMore.setLabel(hasMore ? "loadMore()" : "마지막 row까지 표시됨");
    }
};

// ============================================================================
// DataList 삽입 테스트
// ============================================================================

// setJSON: 전체 데이터 교체
scwin.btnSetJSON_onclick = function (e) {
    scwin.generateRandomData();
};

// setJSON append: 기존 데이터 뒤에 추가
scwin.btnSetJSONAppend_onclick = function (e) {
    scwin.generateRandomData(true);
};

// insertJSON: 특정 위치에 행 삽입
scwin.btnInsertJSON_onclick = function (e) {
    var data = [
        { no: "INS", donateDt: "2025.07.30.", applyDt: "2025.07.30.", procDt: "2025.07.30.", taxId: "101-22-345**", donor: "신규추가테스트", issueTp: "사업자등록번호", donateTp: "종교단체외일반(지정)", gubun: "현금", refNo: "99", amt: "99999" }
    ];
    dataList1.insertJSON(0, data);  // 0번째 위치에 삽입
};

// setRowJSON: 특정 행 데이터 교체
scwin.btnSetRowJSON_onclick = function (e) {
    var cnt = dataList1.getRowCount();
    if (cnt === 0) {
        console.log("데이터가 없습니다.");
        return;
    }
    var rowData = { no: "MOD", donateDt: "2025.07.30.", applyDt: "2025.07.30.", procDt: "2025.07.30.", taxId: "99999********", donor: "행교체테스트", issueTp: "주민등록번호", donateTp: "특례(법정)", gubun: "현금", refNo: "88", amt: "88888" };
    dataList1.setRowJSON(0, rowData, true);  // 0번째 행 교체
};

// ============================================================================
// DataList 수정 테스트
// ============================================================================

// setCellData: 특정 셀 데이터 수정
scwin.btnSetCellData_onclick = function (e) {
    var cnt = dataList1.getRowCount();
    if (cnt === 0) {
        console.log("데이터가 없습니다.");
        return;
    }
    dataList1.setCellData(0, "donor", "셀수정완료");  // 0번째 행의 donor 컬럼 수정
};

// ============================================================================
// DataList 삭제 테스트
// ============================================================================

// removeRows: 여러 행 삭제
scwin.btnRemoveRows_onclick = function (e) {
    var cnt = dataList1.getRowCount();
    if (cnt < 2) {
        console.log("행이 2개 이상 필요합니다. 현재: " + cnt);
        return;
    }
    dataList1.removeRows([0, 1]);  // 0, 1번째 행 삭제
};

// removeRow: 단일 행 삭제
scwin.btnRemoveRow_onclick = function (e) {
    var cnt = dataList1.getRowCount();
    if (cnt === 0) {
        console.log("데이터가 없습니다.");
        return;
    }
    dataList1.removeRow(0);  // 0번째 행 삭제
};

// removeAll: 전체 삭제
scwin.btnRemoveAll_onclick = function (e) {
    dataList1.removeAll();
};

// ============================================================================
// 체크박스 기능
// ============================================================================

// 전체선택 체크박스 변경 시
scwin.checkAll_onchange = function(info) {
    var isChecked = checkAll.getValue() === "1";
    var viewRowCount = listView1.getViewRowCount();

    for (var i = 0; i < viewRowCount; i++) {
        var chkComp = listView1.getCellComponentById(i, "checkbox1");
        if (chkComp) {
            chkComp.setValue(isChecked ? "1" : "");
        }
    }
};

// 선택삭제 버튼 클릭
scwin.btnSelectDelete_onclick = function(e) {
    var checkedIndexes = scwin.getCheckedRowIndexes();
    if (checkedIndexes.length === 0) {
        alert("선택된 행이 없습니다.");
        return;
    }

    // 역순으로 삭제해야 인덱스가 밀리지 않음
    checkedIndexes.sort(function(a, b) { return b - a; });
    for (var i = 0; i < checkedIndexes.length; i++) {
        dataList1.removeRow(checkedIndexes[i]);
    }

    // 전체선택 체크박스 해제
    checkAll.setValue("");
};

// 선택된 행의 rowIndex 배열 가져오기
scwin.getCheckedRowIndexes = function() {
    var checkedIndexes = [];
    var viewRowCount = listView1.getViewRowCount();
    var firstRowIdx = listView1.getFirstRowIndex();

    for (var i = 0; i < viewRowCount; i++) {
        var chkComp = listView1.getCellComponentById(i, "checkbox1");
        if (chkComp && chkComp.getValue() === "1") {
            checkedIndexes.push(firstRowIdx + i);  // 절대 인덱스 반환
        }
    }
    return checkedIndexes;
};

// ============================================================================
// DataList 이벤트 테스트
// ============================================================================

// ondataload: DataList 데이터 전체 변경 시 (setJSON, setXML, setData 등)
scwin.dataList1_ondataload = function() {
    console.log("dataList1_ondataload: 데이터 로드 완료, 총 " + dataList1.getRowCount() + "건");
    scwin.updateLoadMoreStatus();
};

// oninsertrow: DataList 행 추가 시 (insertJSON, insertRow 등)
scwin.dataList1_oninsertrow = function(info) {
    var insertedDataObj = info.insertedDataObj;
    var insertedRows = Object.keys(insertedDataObj);
    console.log("dataList1_oninsertrow: " + insertedRows.length + "건 추가됨, rowIndex=" + insertedRows.join(","));
    scwin.updateLoadMoreStatus();
};

// onremoverow: DataList 행 삭제 시 (removeRow, removeRows, removeAll 등)
scwin.dataList1_onremoverow = function(info) {
    var removedDataObj = info.removedDataObj;
    var removedRows = Object.keys(removedDataObj);
    console.log("dataList1_onremoverow: " + removedRows.length + "건 삭제됨, rowIndex=" + removedRows.join(","));
    scwin.updateLoadMoreStatus();
};

// ============================================================================
// ListView 이벤트 테스트
// ============================================================================

// onadaptivechange: Adaptive 모드 변경 시
scwin.listView1_onadaptivechange = function(mode) {
    console.log("listView1_onadaptivechange: " + mode);
};

// ============================================================================
// Adaptive 스타일 포맷터
// ============================================================================
/**
 * adaptiveFormatter는 새로운 페이지 로드 시마다 호출 (PC, Mobile 모드에 따라 스타일 등 변경 가능)
 */
scwin.listView1_adaptiveFormatter = function(info) {
    var mode = info.mode;
    if (mode === "mobile") {
        for (var i = 0; i < info.rows.length; i++) {
            var row = info.rows[i];
            var viewIndex = row.viewIndex;
            var rowElement = $p.getComponentById(row.elementId);
            // 모바일 뷰에서 원하는 동작 작성
        }
    }
};
